/* ============================================================
   Moonlight Tarot · 多語系資料 i18n.js
   繁體中文是內建語言（在 tarot-core.js 裡），這裡放英文與日文。
   卡牌與神諭牌的圖片三語共用，只有文字不同。
   ============================================================ */

const I18N_CARDS = {
  en: {"0":{"name":"The Fool","up":"New beginnings, adventure, innocence, infinite possibility. Set down your baggage and take the first step with trust — the universe will catch you.","rev":"Recklessness, no plan, hesitation. Look before you leap; don't let impulse stand in for courage."},"1":{"name":"The Magician","up":"Creativity, willpower, resourcefulness. You already hold every tool you need — focus your intent and turn the idea into something real.","rev":"Manipulation, wasted potential, scattered aims. Check whether you've spread your energy thin, or used technique to cover a lost purpose."},"2":{"name":"The High Priestess","up":"Intuition, inner wisdom, stillness. The answer isn't out there. Go quiet and listen inward — it already knows.","rev":"Ignored instincts, secrets, surface reading. You may be leaning on analysis and silencing the voice underneath."},"3":{"name":"The Empress","up":"Abundance, nourishment, beauty. Enjoy the senses, treat yourself well, and abundance flows toward you naturally.","rev":"Dependence, blocked creativity, self-neglect. Care for yourself first — you can't pour from an empty cup."},"4":{"name":"The Emperor","up":"Order, responsibility, solid ground. Build your kingdom with discipline and structure; stability is the floor freedom stands on.","rev":"Rigidity, control, misused authority. Rules are a tool, not a cage — knowing when to let go is leadership too."},"5":{"name":"The Hierophant","up":"Tradition, learning, mentorship. Learn from those who walked ahead; find guidance you can actually trust.","rev":"Dogma, blind obedience, time to break form. Someone else's map may not fit your road — questioning is where growth starts."},"6":{"name":"The Lovers","up":"Love, harmony, a real choice. Choose in the direction your heart points; true union comes from shared values.","rev":"Imbalance, clashing values, dodging the decision. Ask whether this bond or this choice makes you more yourself, or less."},"7":{"name":"The Chariot","up":"Will, victory, holding the reins. Harness the opposing forces inside you, aim, and drive — victory goes to whoever keeps going.","rev":"Loss of control, drift, spinning your wheels. Stop and recalibrate; steady hands beat brute speed."},"8":{"name":"Strength","up":"Gentle courage, patience, inner power. Real strength is softness that outlasts force — tame the lion with love, not a whip.","rev":"Self-doubt, inner fear, patience running out. You're stronger than you think; soothe yourself first, then move."},"9":{"name":"The Hermit","up":"Reflection, solitude, seeking truth. Step out of the noise for a while; carry your own lamp and the answer surfaces in the quiet.","rev":"Isolation, refusing help, withdrawing too far. Solitude is a recharge, not an escape — come back and share your light."},"10":{"name":"Wheel of Fortune","up":"A turn, cycles, luck arriving. The wheel is moving — ride it. The change itself is the opportunity.","rev":"Resistance, bad loops, fighting the turn. When the wheel dips, remember it always comes back up. This passes too."},"11":{"name":"Justice","up":"Fairness, cause and effect, honest reckoning. What you planted is bearing fruit. Do the right thing and balance follows.","rev":"Unfairness, dodged responsibility, self-deception. Look honestly at your own part in this — the truth is the only way out."},"12":{"name":"The Hanged Man","up":"A change of view, pause, surrender. When you're stuck, stop struggling. Hang upside down and the sacrifice buys you a new angle.","rev":"Pointless sacrifice, stalling, deadlock. Are you settling or avoiding? Whatever you're gripping, it may be time to let go."},"13":{"name":"Death","up":"Endings and rebirth, transformation, release. A chapter is closing. This isn't loss — it's clearing room for what comes next.","rev":"Resisting change, stagnation, clutching the past. The harder you hold, the more it hurts. Let the old leave so the new can enter."},"14":{"name":"Temperance","up":"Balance, blending, patience. Mix the proportions of your life without rushing — the middle path is your magic.","rev":"Imbalance, excess, running out of patience. Which part of your life is overflowing? Come back to centre; slower is faster."},"15":{"name":"The Devil","up":"Desire, bondage, facing the shadow. See the chain that binds you — look closer, it was never locked. You can leave any time.","rev":"Breaking free, waking up, reclaiming yourself. You're loosening the knot. Keep walking toward the light."},"16":{"name":"The Tower","up":"Sudden change, collapse, truth exposed. What was built on a false foundation will fall. Let it — only then can you rebuild something real.","rev":"A near miss, delayed collapse, fear of change. Better to dismantle the unstable structure yourself than wait for it to come down."},"17":{"name":"The Star","up":"Hope, healing, inspiration. The quiet sky after the storm. Your wish is being heard — keep trusting.","rev":"Lost faith, pessimism, disconnection. The stars never left; the clouds just moved in. Look up one more time."},"18":{"name":"The Moon","up":"The subconscious, dreams, uncertainty. When the road ahead blurs, fear enlarges every shadow. Walk through — the fog lifts.","rev":"Fear dissolving, truth surfacing, finding your way out. You're leaving the fog behind; dawn is right ahead."},"19":{"name":"The Sun","up":"Joy, success, vitality. The brightest card in the deck. The light is on you — celebrate, and shine without apology.","rev":"A passing cloud, over-optimism, a bruised inner child. The sun is still there, just overcast today. Joy needs your permission."},"20":{"name":"Judgement","up":"Awakening, a calling, rebirth. The reckoning has come. Forgive yourself and answer the deeper call.","rev":"Self-criticism, ignoring the call, stuck in the past. Stop putting yourself on trial. You've done enough."},"21":{"name":"The World","up":"Completion, wholeness, integration. A great cycle closes beautifully. Celebrate what you built and get ready for the next journey.","rev":"Unfinished, one piece missing, success delayed. You're one step from the finish — don't stop at ninety-nine percent."},"22":{"name":"Ace of Wands","up":"A spark of inspiration, the start of action, creative surge. A promising opening is catching fire — follow the heat.","rev":"Delay, low drive, the spark fizzling. The ember is still there; first clear away the kindling that distracts you."},"23":{"name":"Two of Wands","up":"Planning ahead, wider horizons, taking the lead. You stand at the start looking far out — time to turn the vision into a map.","rev":"Fear of the unknown, plans stalling, thinking too small. Map drawn but afraid to leave? The answer is outside the door."},"24":{"name":"Three of Wands","up":"Foresight, expansion, waiting on results. The ships you sent are returning. Keep faith and set up the next move.","rev":"Obstacles, delays, plans knocked back. A late ship isn't a sunk ship — check whether you underestimated the voyage."},"25":{"name":"Four of Wands","up":"Celebration, solid ground, belonging. A real milestone worth marking. Home is your stronghold.","rev":"A transition, unsettled ground, the party postponed. The foundation is still being poured — don't book the celebration yet."},"26":{"name":"Five of Wands","up":"Competition, clashing views, sparring. Friction isn't all bad; healthy competition makes everyone sharper.","rev":"Avoiding conflict, inner contradiction, tension easing. Some fights aren't worth having. Pick the battlefield that matters."},"27":{"name":"Six of Wands","up":"Victory, public recognition, the triumphant return. Your effort has been seen. Enjoy the applause — and stay humble.","rev":"Arrogance, a fall, recognition delayed. Applause is borrowed; the skill is what's actually yours."},"28":{"name":"Seven of Wands","up":"Holding your ground, one against many, defending what you built. You hold the high ground — you only lose if you quit.","rev":"Overwhelmed, exhausted by defending, ready to fold. If you can't hold everything, hold what matters most. A strategic retreat isn't shameful."},"29":{"name":"Eight of Wands","up":"Rapid movement, news flying in, things speeding up. It's all suddenly in motion — hold on and ride it.","rev":"Delays, confusion, haste making waste. The messages are stuck in traffic. Rushing won't help — do the work in front of you."},"30":{"name":"Nine of Wands","up":"Resilience, the last line, courage carrying scars. You've come this far. One more mile.","rev":"Exhaustion, paranoia, over-defending. Put the shield down and rest — not everyone is an enemy."},"31":{"name":"Ten of Wands","up":"Burden, weight of responsibility, carrying too much. You're near the end, but ask which of these loads were never yours.","rev":"Setting it down, learning to delegate, near breaking point. Letting go isn't failure — it's judgement."},"32":{"name":"Page of Wands","up":"A message of enthusiasm, exploring new ground, beginner's fire. Try it with a child's curiosity; even getting it wrong is a gain.","rev":"A passing fad, unclear direction, bad news. Passion needs discipline for fuel, or it burns out and leaves nothing."},"33":{"name":"Knight of Wands","up":"Adventure, bold action, magnetism. Full-speed energy — the world makes room for people who charge.","rev":"Recklessness, overshooting, all noise and no rain. Great engine, but where's the steering? Think first, then floor it."},"34":{"name":"Queen of Wands","up":"Confidence, warm leadership, independence. You radiate light and heat that draws people in. Show yourself fully.","rev":"Jealousy, shaken confidence, running on empty. Tend your own fire first — that's what lets you warm anyone else."},"35":{"name":"King of Wands","up":"Visionary leadership, decisiveness, opening new ground. You can turn a bold vision into reality and bring people with you.","rev":"Domineering, short-tempered, expecting too much. Leading is lighting others up, not burning them out."},"36":{"name":"Ace of Cups","up":"New feeling, intuition welling up, an overflowing heart. Love is flowing toward you — open up and catch it.","rev":"Suppressed emotion, a closed heart, a missed connection. An upturned cup can't hold water. Turn your heart right side up first."},"37":{"name":"Two of Cups","up":"Mutual attraction, partnership, meeting of minds. An equal and lovely connection is forming. Treasure it.","rev":"Imbalance, misunderstanding, strain. The scales have tipped. An honest conversation beats a cold war."},"38":{"name":"Three of Cups","up":"Friendship, celebration, community. Raise a glass with the people who get you — the joy doubles.","rev":"Overindulgence, gossip, social fatigue. Too many parties leave you emptier. Choose the gatherings that are real."},"39":{"name":"Four of Cups","up":"Apathy, reassessment, numbness to what you have. You're bored of the cup in front of you — but don't miss the new one being offered.","rev":"Coming out of the slump, fresh motivation, accepting the offer. You've woken up. The world was interesting the whole time."},"40":{"name":"Five of Cups","up":"Loss, grief, fixating on what's gone. Three cups spilled — but two still stand behind you. Turn around.","rev":"Acceptance, letting go, starting again. The tears are done. Pick up what's left and walk on."},"41":{"name":"Six of Cups","up":"Nostalgia, childhood, uncomplicated kindness. The good of the past feeds the present. Maybe it's time to call an old friend.","rev":"Stuck in the past, refusing to grow up, unable to release. Memory is a place to visit, not to live."},"42":{"name":"Seven of Cups","up":"Fantasy, too many options, daydreaming. All seven cups look tempting, but only one is real. Choose with your heart, not your eyes.","rev":"Clarity, deciding, feet on the ground. The fog cleared. You finally know what you want."},"43":{"name":"Eight of Cups","up":"Walking away, seeking deeper meaning, turning around bravely. The cups are all stacked and still you're unsatisfied — because what your soul wants is over the mountain.","rev":"Avoidance, fear of change, going back and forth. Is this a search or an escape? Only you know."},"44":{"name":"Nine of Cups","up":"A wish granted, contentment, savouring the result. This is the wish card. You've earned what's in front of you.","rev":"Greed, surface happiness, never enough. Have plenty and still unhappy? Maybe the wish was aimed wrong."},"45":{"name":"Ten of Cups","up":"Fulfilment, family happiness, the emotional rainbow. Every layer of love is in place — this is the home you were building.","rev":"Discord, clashing values, the gap between ideal and real. The perfect family doesn't exist. The genuinely loving one does."},"46":{"name":"Page of Cups","up":"A creative message, an invitation from intuition, feelings budding. A fish pokes out of the cup to speak to you — listen to the odd little inspirations.","rev":"Emotional immaturity, sentimentality, blocked creativity. Feelings are precious, but don't let them flood you."},"47":{"name":"Knight of Cups","up":"Romance, chasing an ideal, moving with grace. A knight arrives bearing a cup — it might be love, it might be a dream.","rev":"Unrealistic, over-emotional, promises without substance. Romance is lovely, but watch whether the words match the actions."},"48":{"name":"Queen of Cups","up":"Empathy, intuition, tender care. You feel what others can't. That's a gift — use it to look after people.","rev":"Emotional dependence, over-sensitivity, drowning in feeling. Fill your own cup before you pour for anyone else."},"49":{"name":"King of Cups","up":"Emotional maturity, acceptance, strength through softness. You sit steady on an ocean of feeling — you feel everything without being swept away.","rev":"Emotional manipulation, suppression, unpredictable moods. Controlling others with feeling, or burying your own, both raise the storm."},"50":{"name":"Ace of Swords","up":"Breakthrough, truth, mental clarity. A new blade cuts through the fog. It's time to see the facts plainly.","rev":"Confusion, misjudgement, truth distorted. Don't swing a dull blade — sharpen your thinking first."},"51":{"name":"Two of Swords","up":"Stalemate, a hard choice, blindfolded balance. You're keeping the peace by not deciding — but delay is itself a decision.","rev":"The deadlock breaks, information surfaces, you have to face it. The blindfold slipped. What must be seen will be seen."},"52":{"name":"Three of Swords","up":"Heartbreak, painful truth, grief. Three blades through the heart hurts — but clear pain beats vague misery. Let it finish hurting.","rev":"Healing beginning, forgiveness, drawing the blade out. The wound is closing. Stop pushing the knife back in."},"53":{"name":"Four of Swords","up":"Rest, recovery, a temporary truce. Lying down isn't surrender; it's stocking up for the next round.","rev":"Burnout, refusing rest, back into the fray. Keep skipping rest and your body will schedule it for you."},"54":{"name":"Five of Swords","up":"Conflict, a hollow win, a high price. You won the battle and lost the relationship. Was it worth it?","rev":"Reconciliation, dropping the grudge, leaving the field. Some scores stop mattering. Pick up your dignity and go."},"55":{"name":"Six of Swords","up":"Transition, leaving the storm, sailing toward calm. The boat is carrying you out of it. Glance back once — don't jump back in.","rev":"Unable to move on, unfinished lessons, too much luggage. The boat won't move because you're still dragging the anchor."},"56":{"name":"Seven of Swords","up":"Strategy, misdirection, acting alone. Not every card has to be face up. Be clever, but keep your line.","rev":"Coming clean, conscience catching up, the plan exposed. Paper can't wrap fire. Honesty is the cheapest strategy."},"57":{"name":"Eight of Swords","up":"Self-imposed limits, feeling trapped, a prison of fear. The rope holding you is loose — and you tied the blindfold yourself.","rev":"Breaking loose, a new angle, freedom regained. You noticed: the door was never locked."},"58":{"name":"Nine of Swords","up":"Anxiety, sleeplessness, nightmares. The three-a.m. disaster script — ninety percent of it won't happen. What you need is daylight, not an answer.","rev":"Coming out of the dark, asking for help, waking from the nightmare. The moment you say it out loud, the monster halves."},"59":{"name":"Ten of Swords","up":"An ending, rock bottom, the darkest hour. Ten blades in the back is genuinely grim — but look: the horizon is brightening. The good thing about the bottom is that the only way is up.","rev":"Bouncing back, rebirth, survival. You made it through. Scarred, but standing."},"60":{"name":"Page of Swords","up":"Curiosity, alertness, hunger to know. Watch and learn like a detective — but verify before you repeat.","rev":"Gossip, surveillance, words that wound. Your tongue is a blade too. Sheath it."},"61":{"name":"Knight of Swords","up":"Decisiveness, charging the target, swift execution. Once it's clear, go at full speed — hesitation is the expensive option.","rev":"Recklessness, aggression, rushing for its own sake. Fast isn't the same as right. Confirm the direction before you accelerate."},"62":{"name":"Queen of Swords","up":"Clear thinking, independence, cutting to the point. You see through the spin to what's underneath — clean boundaries are your superpower.","rev":"Coldness, sharpness, walls too high. Reason is armour, not a weapon. Let the heart speak sometimes."},"63":{"name":"King of Swords","up":"Wise authority, truth, fair judgement. Use a clear head for the hard call. Feelings to one side, facts in the middle.","rev":"Abused power, coldness, arguing to win. The sharpest blade needs the warmest hand to hold it."},"64":{"name":"Ace of Pentacles","up":"A new financial opening, a practical start, a seed landing. A golden seed is placed in your hand. Plant it properly and it grows.","rev":"A missed opening, greed, unstable ground. Chances usually slip because you grabbed for too many at once."},"65":{"name":"Two of Pentacles","up":"Juggling, flexibility, handling it with room to spare. You're tossing several balls with skill — keep one hand free for the unexpected.","rev":"Overloaded, dropping things, robbing one to pay the other. Too many balls? Put some down. Nobody catches them all."},"66":{"name":"Three of Pentacles","up":"Teamwork, craft recognised, building together. Your skill is being seen. Build the cathedral with the right people.","rev":"Working at cross purposes, compromised quality, going it alone. One person moves fast; a group builds tall."},"67":{"name":"Four of Pentacles","up":"Security, saving, holding what you earned. You're clutching the coins you worked for. Safety is good — just don't hold until your hands go numb.","rev":"Stinginess, over-control, gripping too tight. Money is moving energy; squeezed hard enough, it stops growing."},"68":{"name":"Five of Pentacles","up":"Financial hardship, scarcity, walking through the snow. The winter is real — but so is the lit window. Asking for help isn't shameful.","rev":"Coming out of it, help arriving, the snow stopping. The hardest stretch is passing. The door was open the whole time."},"69":{"name":"Six of Pentacles","up":"Generosity, giving and receiving in balance, resources flowing. Today you're the one giving; tomorrow you may be receiving. Keep the kindness circulating.","rev":"Giving with strings, debt, charity with a sneer. Real giving doesn't keep accounts."},"70":{"name":"Seven of Pentacles","up":"Waiting for the harvest, assessing progress, playing long. You planted the tree — stop digging it up to check the roots. Time is working for you.","rev":"Impatience, anxiety at no visible result, wanting to quit. The first half of compounding always looks like this: dull, slow, then suddenly startling."},"71":{"name":"Eight of Pentacles","up":"Honing the craft, diligence, the artisan's mind. One coin struck at a time — you're on the road to mastery.","rev":"Going through the motions, perfectionism, busy but idle. Repetition isn't improvement. Strike each one with attention."},"72":{"name":"Nine of Pentacles","up":"Abundance, self-sufficiency, elegant independence. You walk in a garden you built yourself — you earned every bit of this.","rev":"Overwork, showing off, gilded on the outside. Lovely garden. Do you ever have time to walk in it?"},"73":{"name":"Ten of Pentacles","up":"Lasting wealth, family abundance, long-term security. This is the financial-freedom card — what you're building isn't just money, it's a foundation that can be handed on.","rev":"Financial disputes, instability, short-term thinking. Real wealth is a tree three generations can sit under."},"74":{"name":"Page of Pentacles","up":"Learning a skill, a practical start, a grounded dream. The apprentice studying the coin in their hands — your learning is on its way to paying.","rev":"Procrastination, no progress, talk without practice. A dream on paper doesn't appreciate. Doing it does."},"75":{"name":"Knight of Pentacles","up":"Steady progress, reliability, slow but certain. This horse isn't fast, but it never leaves the road — routine is your superpower.","rev":"Stagnation, tedium, over-caution. Steady is good, but let the horse trot occasionally."},"76":{"name":"Queen of Pentacles","up":"Practical nurture, builder of safety, generous care. You can keep the accounts and feed the family at once — an underrated talent.","rev":"Work-life imbalance, self-neglect, money anxiety. Before you look after everyone, remember you're on the list too."},"77":{"name":"King of Pentacles","up":"Wealth, established success, a reliable provider. You sit in an abundant kingdom you built — enjoy it, and protect it.","rev":"Greed, materialism, measuring everything in money. A king's greatest wealth is knowing when enough is enough."}},
  ja: {"0":{"name":"愚者","up":"新しい始まり、冒険、純粋さ、無限の可能性。荷物を下ろして、信じて一歩を踏み出してください。宇宙が受けとめてくれます。","rev":"無謀、計画のなさ、ためらい。飛ぶ前に足元を確かめて。衝動を勇気とすり替えないこと。"},"1":{"name":"魔術師","up":"創造力、意志の力、資源をまとめる力。必要な道具はすでにあなたの手の中に。意識を集中させて、考えを形にしましょう。","rev":"操作、活かされない才能、目的の混乱。力が散らばっていないか、技術で初心を覆っていないか見直して。"},"2":{"name":"女教皇","up":"直感、内なる知恵、静けさ。答えは外にはありません。静かになって内側の声を聴いて。それはもう知っています。","rev":"直感の無視、秘密、表面的な理解。頭で考えすぎて、内側の声を押し殺しているかもしれません。"},"3":{"name":"女帝","up":"豊かさ、育み、美しさ。五感の喜びを味わい、自分をいたわって。豊かさは自然に流れ込んできます。","rev":"依存、創造性の停滞、自分をおろそかにすること。まず自分を満たして。空の器からは注げません。"},"4":{"name":"皇帝","up":"秩序、責任、揺るがない土台。規律と構造で自分の王国を築いて。安定は自由が立つ床です。","rev":"硬直、支配欲、権威の乱用。ルールは道具であって檻ではありません。手放すことも力です。"},"5":{"name":"教皇","up":"伝統、学び、導き手。先を歩いた人の知恵から学び、信頼できる導きを探して。","rev":"教条主義、盲従、型を破る時。他人の地図はあなたの道に合わないかも。疑うことが成長の始まりです。"},"6":{"name":"恋人","up":"愛、調和、大切な選択。心が指す方へ選んで。本当の結びつきは価値観の一致から生まれます。","rev":"不均衡、価値観のずれ、決断からの逃避。この関係やこの選択が、あなたをより自分らしくするか確かめて。"},"7":{"name":"戦車","up":"意志、勝利、舵を握ること。内側の相反する力を御して、目標へ進んで。勝利は続けた人のものです。","rev":"制御不能、方向の見失い、空回り。一度止まって進路を測り直して。力任せより手綱の安定です。"},"8":{"name":"力","up":"やさしい勇気、忍耐、内なる強さ。本当の強さは柔らかさ。鞭ではなく愛で獅子を手なずけて。","rev":"自信のなさ、内なる恐れ、忍耐の消耗。あなたは思うより強い。まず自分をなだめてから動いて。"},"9":{"name":"隠者","up":"内省、ひとりの時間、真理の探究。喧噪から少し離れて。自分の灯を掲げれば、静けさの中で答えが浮かびます。","rev":"孤立、助けの拒絶、引きこもりすぎ。孤独は充電であって逃避ではありません。戻って光を分かち合って。"},"10":{"name":"運命の輪","up":"転機、めぐり、幸運の到来。輪は回っています。流れに乗って。変化そのものが機会です。","rev":"抵抗、悪い循環、変化への拒絶。輪が下がっている時も、必ずまた上がります。これも過ぎていきます。"},"11":{"name":"正義","up":"公平、因果、正直な清算。蒔いた種が実っています。正しいことをすれば、均衡は自ずと訪れます。","rev":"不公平、責任からの逃避、自己欺瞞。この件での自分の役割を正直に見て。真実だけが出口です。"},"12":{"name":"吊るされた男","up":"視点の転換、休止、明け渡し。行き詰まったらもがかないで。逆さから見れば、犠牲が新しい視界を買ってくれます。","rev":"無意味な犠牲、先延ばし、膠着。沈殿しているのか逃げているのか。手放すべき執着は手放して。"},"13":{"name":"死神","up":"終わりと再生、変容、手放し。一つの章が閉じています。これは喪失ではなく、次のための余白づくりです。","rev":"変化への抵抗、停滞、過去へのしがみつき。抗うほど苦しくなります。古いものを去らせて、新しいものを迎えて。"},"14":{"name":"節制","up":"バランス、調和、忍耐。急がず焦らず生活の配分を整えて。中庸があなたの魔法です。","rev":"不均衡、過剰、忍耐の欠如。どの部分が過ぎていますか。真ん中に戻って。ゆっくりの方が速い。"},"15":{"name":"悪魔","up":"欲望、束縛、影と向き合うこと。あなたを縛る鎖をよく見て。実は鍵はかかっていません。いつでも出られます。","rev":"解放、目覚め、自由の回復。緩み始めています。光の方へ歩き続けて。"},"16":{"name":"塔","up":"急変、崩壊、真実の露呈。誤った土台の上のものは必ず崩れます。崩れさせて。そこからしか本物は建ちません。","rev":"間一髪、遅れてくる崩壊、変化への恐れ。崩れるのを待つより、自分で不安定な構造を解体して。"},"17":{"name":"星","up":"希望、癒し、ひらめき。嵐のあとの静かな夜空。願いは届いています。信じ続けて。","rev":"自信の喪失、悲観、内側との断絶。星はずっとそこにあります。雲に隠れているだけ。もう一度見上げて。"},"18":{"name":"月","up":"潜在意識、夢、不確かさ。先が霞むと、恐れが影を大きくします。歩き抜けて。霧は晴れます。","rev":"恐れの解消、真実の浮上、迷いからの脱出。霧の領域を抜けつつあります。夜明けはすぐ前です。"},"19":{"name":"太陽","up":"喜び、成功、生命力。デッキで最も明るい札。光があなたに当たっています。祝って、遠慮なく輝いて。","rev":"一時的な曇り、楽観しすぎ、傷ついた内なる子ども。太陽はまだあります。今日は曇りなだけ。喜びには許可が要ります。"},"20":{"name":"審判","up":"目覚め、呼びかけ、再生。総括の時が来ました。自分を許して、より深い呼び声に応えて。","rev":"自己批判、呼び声の無視、過去への囚われ。自分を裁くのをやめて。もう十分やってきました。"},"21":{"name":"世界","up":"完成、円満、統合。大きな循環が美しく閉じます。築いたものを祝って、次の旅の支度を。","rev":"未完成、あと一片、遅れる成功。ゴールまであと一歩。九十九パーセントで止まらないで。"},"22":{"name":"ワンドのエース","up":"ひらめきの火、行動の始まり、創造力の噴出。可能性のある機会が燃え始めています。熱の方へ。","rev":"遅れ、意欲の低下、火種の消えかけ。種火はまだあります。まず気を散らす薪を片付けて。"},"23":{"name":"ワンドの2","up":"未来の計画、広い視野、主導権。出発点から遠くを眺めています。構想を地図に変える時。","rev":"未知への恐れ、計画の停滞、視野の狭さ。地図は描けたのに出られない？答えは扉の外です。"},"24":{"name":"ワンドの3","up":"先見、拡大、成果を待つこと。送り出した船が戻りつつあります。信じて、次の布石を。","rev":"障害、遅延、計画のつまずき。船が遅いだけで沈んだわけではありません。航程を甘く見ていないか確認を。"},"25":{"name":"ワンドの4","up":"祝福、安定した土台、居場所。節目はきちんと祝う価値があります。家はあなたの砦です。","rev":"移行期、落ち着かなさ、祝いの延期。土台はまだ打っている最中。宴の準備は早い。"},"26":{"name":"ワンドの5","up":"競争、意見の衝突、切磋琢磨。摩擦は悪いだけではありません。健全な競争は互いを強くします。","rev":"衝突の回避、内なる矛盾、緊張の緩和。戦う価値のない喧嘩もあります。戦場を選んで。"},"27":{"name":"ワンドの6","up":"勝利、周囲からの承認、凱旋。努力が見られました。拍手を受け取り、そして謙虚に。","rev":"慢心、転落、遅れる評価。拍手は借り物、実力だけが自分のものです。"},"28":{"name":"ワンドの7","up":"立場を守ること、一対多、成果の防衛。高地を占めています。諦めない限り負けません。","rev":"消耗、守りの疲れ、投げ出したさ。全部は守れないなら、最も大事なものを。戦略的撤退は恥ではありません。"},"29":{"name":"ワンドの8","up":"急速な進展、知らせの到来、加速。すべてが急に動き出しました。しっかり掴んで流れに乗って。","rev":"遅延、混乱、急いては事を仕損じる。連絡が渋滞中。焦らず、手元の仕事を丁寧に。"},"30":{"name":"ワンドの9","up":"粘り強さ、最後の防衛線、傷を抱えた勇気。ここまで来ました。あと一里です。","rev":"疲弊、猜疑、守りすぎ。盾を置いて少し休んで。全員が敵ではありません。"},"31":{"name":"ワンドの10","up":"重荷、責任の重み、背負いすぎ。終点は近い。でも、その荷のどれが本当に自分のものか問いかけて。","rev":"荷を下ろす、任せることを学ぶ、限界寸前。手放すのは失敗ではなく判断です。"},"32":{"name":"ワンドのペイジ","up":"熱意ある知らせ、新しい領域の探索、初心者の火。子どものような好奇心で試して。間違いも収穫です。","rev":"三日坊主、方向の不明瞭さ、悪い知らせ。情熱には規律という薪が要ります。でないと燃え尽きて何も残りません。"},"33":{"name":"ワンドのナイト","up":"冒険、大胆な行動、人を惹きつける力。全速前進の勢い。世界は突っ込む人に道を空けます。","rev":"無謀、行き過ぎ、掛け声倒れ。エンジンは強いけれどハンドルは？考えてから踏んで。"},"34":{"name":"ワンドのクイーン","up":"自信、あたたかい統率力、自立。人を惹きつける光と熱を放っています。堂々と自分を見せて。","rev":"嫉妬、自信のゆらぎ、エネルギー切れ。まず自分の火を世話して。それが誰かを温める力になります。"},"35":{"name":"ワンドのキング","up":"構想力のある指導者、胆力、道を切り拓く力。大胆な構想を現実にし、人を連れていける人です。","rev":"独断、短気、過剰な期待。導くとは人に火を灯すことで、燃やし尽くすことではありません。"},"36":{"name":"カップのエース","up":"新しい感情、直感の湧き出し、満たされる心。愛が流れ込んでいます。心を開いて受け取って。","rev":"感情の抑圧、閉じた心、逃した繋がり。伏せた器に水は入りません。まず心を上向きに。"},"37":{"name":"カップの2","up":"惹かれ合い、対等な関係、心が通うこと。美しく対等な繋がりが育っています。大切に。","rev":"不均衡、誤解、緊張。天秤が傾いています。冷戦より正直な会話を。"},"38":{"name":"カップの3","up":"友情、祝い、仲間の支え。わかってくれる人と杯を上げて。喜びは倍になります。","rev":"過度な放縦、噂話、人付き合いの疲れ。宴が多すぎても空しくなります。本物の集まりを選んで。"},"39":{"name":"カップの4","up":"無関心、見直し、今あるものへの倦み。目の前の杯には飽きた。でも差し出されている新しい杯を見逃さないで。","rev":"停滞からの脱出、新しい意欲、機会を受け入れること。目が覚めました。世界はずっと面白かった。"},"40":{"name":"カップの5","up":"喪失、悲しみ、失ったものへの執着。三つの杯は倒れた。でも後ろにまだ二つ立っています。振り返って。","rev":"受容、手放し、再出発。涙は流し終えました。残った杯を持って歩き出して。"},"41":{"name":"カップの6","up":"懐かしさ、子ども時代、素朴なやさしさ。過去の良きものが今のあなたを養います。旧友に連絡する時かも。","rev":"過去への囚われ、成長の拒否、手放せなさ。思い出は訪ねる場所であって、住む場所ではありません。"},"42":{"name":"カップの7","up":"幻想、選択肢の多さ、白昼夢。七つの杯はどれも魅力的ですが、本物は一つ。目ではなく心で選んで。","rev":"明晰さ、決断、地に足をつけること。霧が晴れました。ようやく自分の望みがわかりました。"},"43":{"name":"カップの8","up":"立ち去ること、より深い意味の探求、勇気ある転身。杯は積み上がったのに満たされない。魂が求めるものは山の向こうにあるから。","rev":"逃避、変化への恐れ、堂々巡り。探求なのか逃走なのか。知っているのはあなただけです。"},"44":{"name":"カップの9","up":"願いの成就、満足、成果を味わうこと。「願いが叶う」札です。今の良さを受け取る資格があります。","rev":"強欲、表面的な喜び、満たされなさ。たくさん持っていても幸せでない？願いの狙いが違ったのかも。"},"45":{"name":"カップの10","up":"円満、家庭の幸せ、感情の虹。愛のあらゆる層が整いました。あなたが築いてきた家です。","rev":"不和、価値観の衝突、理想と現実の差。完璧な家族は存在しません。本当に愛し合う家は存在します。"},"46":{"name":"カップのペイジ","up":"創造的な知らせ、直感からの誘い、芽生える気持ち。杯から魚が顔を出して話しかけてきます。不思議なひらめきに耳を傾けて。","rev":"感情の未熟さ、感傷、創造性の停滞。感じることは尊いけれど、飲み込まれないで。"},"47":{"name":"カップのナイト","up":"ロマンス、理想の追求、優雅な歩み。杯を掲げた騎士が申し出を運んできます。恋かもしれないし、夢かもしれない。","rev":"非現実的、感情的、口約束。ロマンスは美しいけれど、言葉と行いが一致しているか見て。"},"48":{"name":"カップのクイーン","up":"共感、直感、やさしい気づかい。人が感じ取れないものを感じ取れます。それは才能。人を支えるために使って。","rev":"感情的依存、過敏さ、感情に飲まれること。誰かに注ぐ前に、自分の杯を満たして。"},"49":{"name":"カップのキング","up":"感情の成熟、包容、柔よく剛を制す。感情の海の上に静かに座っています。すべてを感じながら、流されない。","rev":"感情による操作、抑圧、気分の起伏。感情で人を動かすのも、自分を抑え込むのも、海を荒れさせます。"},"50":{"name":"ソードのエース","up":"突破、真実、思考の明晰さ。新しい剣が霧を裂きます。事実をはっきり見る時。","rev":"混乱、判断の誤り、歪められた真実。切れない剣を振り回さないで。まず思考を研いで。"},"51":{"name":"ソードの2","up":"膠着、選べない状態、目隠しの均衡。決めないことで平和を保っています。でも先延ばしも一つの決断です。","rev":"膠着の打破、情報の露呈、直面せざるを得ない状況。目隠しが落ちました。見るべきものは結局見ることになります。"},"52":{"name":"ソードの3","up":"心の傷、痛い真実、悲しみ。三本の剣が刺さるのは痛い。でも曖昧な苦しみより、はっきりした痛みの方がまし。痛み切って。","rev":"癒しの始まり、赦し、剣を抜くこと。傷は塞がりつつあります。自分でまた刺し戻さないで。"},"53":{"name":"ソードの4","up":"休息、回復、一時休戦。横になるのは負けではなく、次の戦いのための備蓄です。","rev":"過労、休息の拒否、戦線復帰。休まないと、体が勝手に入院という休みを取ります。"},"54":{"name":"ソードの5","up":"争い、後味の悪い勝利、高すぎる代償。戦いに勝って関係を失う。それは割に合いますか。","rev":"和解、遺恨を手放すこと、戦場を去ること。もう重要でない勝敗もあります。尊厳を拾って立ち去って。"},"55":{"name":"ソードの6","up":"移行、嵐からの離脱、静かな場所へ。船があなたを困難から運び出しています。一度振り返るだけにして、戻らないで。","rev":"進めない状態、未解決の課題、荷物の重さ。船が動かないのは、まだ錨を引きずっているから。"},"56":{"name":"ソードの7","up":"戦略、陽動、単独行動。すべての札を見せる必要はありません。賢く動いて、でも一線は守って。","rev":"告白、良心の呵責、企ての露見。紙は火を包めません。正直が一番省エネな戦略です。"},"57":{"name":"ソードの8","up":"自分で課した制限、閉じ込められた感覚、恐れの檻。縛る縄は実は緩く、目隠しも自分でつけたもの。","rev":"束縛からの脱出、新しい視点、自由の回復。気づきました。扉には鍵などかかっていなかった。"},"58":{"name":"ソードの9","up":"不安、不眠、悪夢。午前三時の破滅の脚本。九割は起きません。必要なのは答えではなく夜明けです。","rev":"暗がりからの脱出、助けを求めること、悪夢からの覚醒。誰かに言葉にした瞬間、怪物は半分に縮みます。"},"59":{"name":"ソードの10","up":"終わり、どん底、最も暗い時間。背中に十本は確かに惨い。でも見て、地平線が明るみ始めています。底の良いところは、上しかないこと。","rev":"底からの反転、再生、生き延びたこと。乗り越えました。傷を抱えて、それでも立っています。"},"60":{"name":"ソードのペイジ","up":"好奇心、警戒、知りたい気持ち。探偵のように観察し学んで。ただし裏を取ってから伝えて。","rev":"噂話、詮索、人を傷つける言葉。舌もまた剣です。しまっておいて。"},"61":{"name":"ソードのナイト","up":"決断、目標への直進、迅速な実行。腹が決まったら全速力で。ためらいが一番高くつきます。","rev":"無謀、高圧的、勢いだけの前進。速いことは正しいことではありません。方向を確かめてから加速を。"},"62":{"name":"ソードのクイーン","up":"理性、自立、核心を突く力。言葉の飾りを見抜いて本質を見ます。境界線をはっきり引けるのがあなたの強みです。","rev":"冷たさ、鋭すぎる言葉、高すぎる心の壁。理性は鎧であって武器ではありません。たまには心に喋らせて。"},"63":{"name":"ソードのキング","up":"知恵ある権威、真実、公正な判断。澄んだ頭で難しい決断を。感情は脇に、事実を真ん中に。","rev":"権力の乱用、冷酷さ、詭弁。最も鋭い剣ほど、あたたかい手で握る必要があります。"},"64":{"name":"ペンタクルのエース","up":"新しい金銭の機会、現実的な始まり、落ちた種。金貨の種があなたの手に。きちんと植えれば育ちます。","rev":"機会の逸失、強欲、不安定な土台。機会が逃げるのは、たいてい一度に掴みすぎたから。"},"65":{"name":"ペンタクルの2","up":"両立、柔軟さ、余裕のあるやりくり。いくつかの球を器用に扱えています。不測のために片手を空けておいて。","rev":"不均衡、手が回らないこと、あちらを立てればこちら。球が多すぎるなら幾つか置いて。全部は誰も受けられません。"},"66":{"name":"ペンタクルの3","up":"協働、技術の評価、共に築くこと。あなたの専門性が見られています。合う人と大聖堂を建てて。","rev":"ばらばらの動き、品質の妥協、孤軍奮闘。一人なら速く、みんなでなら高く建ちます。"},"67":{"name":"ペンタクルの4","up":"安定、蓄え、成果を守ること。稼いだ金貨を抱えています。安心感は良いこと。ただし手が痺れるまで抱えないで。","rev":"けち、過度な管理、握りすぎ。お金は流れる力。握りしめると育ちません。"},"68":{"name":"ペンタクルの5","up":"経済的な困難、欠乏感、雪の中を歩くこと。冬は本物です。でも教会の灯りも本物。助けを求めるのは恥ではありません。","rev":"困難からの脱出、助けの到来、雪の止み。一番きつい区間が過ぎつつあります。扉はずっと開いていました。"},"69":{"name":"ペンタクルの6","up":"惜しみなさ、与えることと受け取ることの均衡、資源の循環。今日は与える側、明日は受け取る側かも。善意を回して。","rev":"条件つきの施し、負債、施しの傲慢。本当の贈与は帳簿をつけません。"},"70":{"name":"ペンタクルの7","up":"収穫を待つこと、進捗の見直し、長い目。木を植えたなら、毎日掘り返して根を見ないで。時間が働いてくれています。","rev":"焦り、成果が見えない不安、投げ出したさ。複利の前半はいつもこうです。退屈で、遅く、そして突然驚くほどに。"},"71":{"name":"ペンタクルの8","up":"技を磨くこと、勤勉、職人の心。一枚ずつ叩いて、名人への道の途中です。","rev":"おざなり、完璧主義、忙しいだけ。繰り返しは上達ではありません。一枚ずつ心を込めて。"},"72":{"name":"ペンタクルの9","up":"豊かさ、自給自足、優雅な自立。自分で造った庭を歩いています。これは全部、自分の力で得たものです。","rev":"働きすぎ、見栄、外面だけの豪華さ。素敵な庭ですね。散歩する時間はありますか。"},"73":{"name":"ペンタクルの10","up":"受け継がれる富、一族の豊かさ、長期の安心。「経済的自由」の札です。築いているのは富だけでなく、受け渡せる土台です。","rev":"金銭の揉め事、不安定さ、目先の利益。本当の富は、三世代が木陰に座れる樹です。"},"74":{"name":"ペンタクルのペイジ","up":"技能の習得、堅実な出発、地に足のついた夢。金貨を手に熱心に学ぶ見習い。学びが形になっていく途中です。","rev":"先延ばし、進展のなさ、口だけ。紙の上の夢は増えません。手を動かすと増えます。"},"75":{"name":"ペンタクルのナイト","up":"着実な歩み、信頼できること、遅くとも必ず着く。この馬は速くないけれど、決して道を外れません。淡々とやれるのが強みです。","rev":"停滞、退屈、慎重すぎ。堅実は良いこと。でもたまには馬を小走りさせて。"},"76":{"name":"ペンタクルのクイーン","up":"現実的な育み、安心を作る人、豊かな気づかい。財布と家族の食卓を同時に守れる。過小評価されがちな才能です。","rev":"仕事と家庭の不均衡、自分の後回し、物質的な不安。全員の面倒を見る前に、名簿に自分もいることを思い出して。"},"77":{"name":"ペンタクルのキング","up":"富、事業の成功、頼れる担い手。自分で築いた豊かな王国に座っています。享受して、そして守って。","rev":"強欲、物質主義、すべてをお金で測ること。王の最大の富は、これ以上要らないと知っていることです。"}}
};

