// ===== 語言偵測與切換 =====
const SUPPORTED_LANGS = ['zh', 'en', 'ja'];
function detectLang() {
  try {
    const saved = localStorage.getItem('ml_lang');
    if (saved && SUPPORTED_LANGS.indexOf(saved) >= 0) return saved;
  } catch (e) {}
  const nav = (navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || 'zh'])
    .map(x => String(x).toLowerCase());
  for (const l of nav) {
    if (l.indexOf('zh') === 0) return 'zh';
    if (l.indexOf('ja') === 0) return 'ja';
    if (l.indexOf('en') === 0) return 'en';
  }
  return 'en';   // 其他語言的訪客給英文，比中文好懂
}
let LANG = detectLang();
function setLang(l) {
  if (SUPPORTED_LANGS.indexOf(l) < 0) return;
  try { localStorage.setItem('ml_lang', l); } catch (e) {}
  location.reload();
}
// 介面字串
function t(key, vars) {
  const pack = I18N_UI[LANG] || I18N_UI.zh;
  let s = pack[key] !== undefined ? pack[key] : (I18N_UI.zh[key] || key);
  if (vars) Object.keys(vars).forEach(k => { s = s.split('{' + k + '}').join(vars[k]); });
  return s;
}
